mapper.select:
SELECT cr.*, s.name AS scenic_spot_name, u.real_name AS operator_name FROM check_in_record cr LEFT JOIN scenic_spot s ON cr.scenic_spot_id = s.id LEFT JOIN sys_user u ON cr.operator_id = u.id WHERE 1=1
AND cr.scenic_spot_id = #{scenicSpotId}
AND cr.status = #{status}
AND DATE(cr.check_in_time) = #{date}
ORDER BY cr.check_in_time DESC

SELECT DATE(check_in_time) AS date, COUNT(*) AS visitor_count FROM check_in_record WHERE 1=1
AND DATE(check_in_time) >= #{startDate}
AND DATE(check_in_time) <= #{endDate}
GROUP BY DATE(check_in_time) ORDER BY DATE(check_in_time)
